"""matplotlib._animation_data — HTML5-video embed template stub.

Real matplotlib uses these strings when serializing an animation to
embedded HTML for Jupyter (`anim.to_jshtml()` / `anim.to_html5_video()`).
The plotly backend has its own animation pipeline so these constants
are not consumed, but we expose them as empty strings so direct imports
(`from matplotlib._animation_data import JS_INCLUDE`) succeed.
"""

JS_INCLUDE = ''
DISPLAY_TEMPLATE = ''
INCLUDED_FRAMES = ''
STYLE_INCLUDE = ''
